pub fn string_to_u16(string: &str) -> Option<u16> {
	STRING_TO_U16.get(string).copied()
}

impl Item {
    pub const fn get_properties(self) -> &'static ItemProperties {
        &ITEM_PROPERTIES_LUT[self as usize]
    }
}

#[derive(Debug)]
pub struct ItemProperties {
	pub max_stack_size: u8,
	pub default_components: enumset::EnumSet<DataComponentType>,
	pub default_component_hashes: enum_map::EnumMap<DataComponentType, Option<i32>>,
	pub corresponding_block: Option<u16>,
}

